    (11071621::bigint, 'Normandie', NULL::jsonb, '28', 3017382::bigint, 'country', NULL::text),
    (11071622::bigint, 'Grand Est', NULL::jsonb, '44', 3017382::bigint, 'country', NULL::text),
    (11071623::bigint, 'Occitanie', NULL::jsonb, '76', 3017382::bigint, 'country', NULL::text),
    (11071624::bigint, 'Hauts-de-France', NULL::jsonb, '32', 3017382::bigint, 'country', NULL::text),
    (11071625::bigint, 'Auvergne-Rhône-Alpes', NULL::jsonb, '84', 3017382::bigint, 'country', NULL::text),
    (NULL::bigint, 'Mayotte', NULL::jsonb, '06', 3017382::bigint, 'country', NULL::text)
) AS v(geonames_id, name, name_i18n, external_code, parent_geonames_id, parent_type, parent_external_code)
JOIN public.locations p
  ON p.country_code = 'FR'
 AND p.type = v.parent_type::public.location_type
 AND p.geonames_id = v.parent_geonames_id
WHERE NOT EXISTS (
  SELECT 1 FROM public.locations l
   WHERE CASE WHEN v.geonames_id IS NULL
              THEN l.country_code = 'FR' AND l.type = 'region' AND l.external_code = v.external_code
              ELSE l.geonames_id = v.geonames_id
         END
);

