JOIN public.locations p
  ON p.country_code = 'FR'
 AND p.type = v.parent_type::public.location_type
 AND CASE WHEN v.parent_geonames_id IS NULL
          THEN p.external_code = v.parent_external_code
          ELSE p.geonames_id = v.parent_geonames_id
     END
WHERE NOT EXISTS (
  SELECT 1 FROM public.locations l WHERE l.geonames_id = v.geonames_id
);

-- Fail the migration if the seed did not land whole.
--
-- A partial seed is worse than none: it is a hole in the tree an admin browses
-- and a gedu claims coverage over — places that simply are not there, with
-- nothing pointing at the cause. Every count is exact rather than "at least",
-- because a surplus means rows exist that this seed does not explain, and that
-- wants a human rather than a pass.
--
-- The counts here are the national statistical agency's, carried through the
-- generator's own gate; they are restated in SQL because this file can be
-- applied by hand long after that gate ran.
DO $$
DECLARE
  n_country integer;
  n_region integer;
  n_district integer;
  n_municipality integer;
  n_codeless integer;
  n_keyless integer;
  n_dupes integer;
  orphans integer;
BEGIN
  SELECT count(*) INTO n_country
    FROM public.locations
   WHERE country_code = 'FR' AND type = 'country';

  IF n_country <> 1 THEN
    RAISE EXCEPTION 'France GeoNames seed: expected exactly 1 FR country row, found %', n_country;
  END IF;

  SELECT count(*) INTO n_region
    FROM public.locations
   WHERE country_code = 'FR' AND type = 'region';

  IF n_region <> 18 THEN
    RAISE EXCEPTION
      'France GeoNames seed: expected 18 region rows for FR, found %. A shortfall means a level above did not land; a surplus means rows exist this seed does not explain.',
      n_region;
  END IF;

  -- Orphans, LEFT JOIN shape: a NULL or dangling parent_id has to be visible,
  -- which an inner join would silently drop.
  SELECT count(*) INTO orphans
    FROM public.locations c
    LEFT JOIN public.locations p ON p.id = c.parent_id
   WHERE c.country_code = 'FR' AND c.type = 'region'
     AND (p.id IS NULL OR p.country_code <> 'FR' OR p.type <> 'country');

  IF orphans > 0 THEN
    RAISE EXCEPTION 'France GeoNames seed: % region rows are not parented to a country row in FR', orphans;
  END IF;

  SELECT count(*) INTO n_district
    FROM public.locations
   WHERE country_code = 'FR' AND type = 'district';

  IF n_district <> 101 THEN
    RAISE EXCEPTION
      'France GeoNames seed: expected 101 district rows for FR, found %. A shortfall means a level above did not land; a surplus means rows exist this seed does not explain.',
      n_district;
  END IF;

  -- Orphans, LEFT JOIN shape: a NULL or dangling parent_id has to be visible,
  -- which an inner join would silently drop.
  SELECT count(*) INTO orphans
    FROM public.locations c
    LEFT JOIN public.locations p ON p.id = c.parent_id
   WHERE c.country_code = 'FR' AND c.type = 'district'
     AND (p.id IS NULL OR p.country_code <> 'FR' OR p.type <> 'region');

  IF orphans > 0 THEN
    RAISE EXCEPTION 'France GeoNames seed: % district rows are not parented to a region row in FR', orphans;
  END IF;

  SELECT count(*) INTO n_municipality
    FROM public.locations
   WHERE country_code = 'FR' AND type = 'municipality';

  IF n_municipality <> 34871 THEN
    RAISE EXCEPTION
      'France GeoNames seed: expected 34871 municipality rows for FR, found %. A shortfall means a level above did not land; a surplus means rows exist this seed does not explain.',
      n_municipality;
  END IF;

  -- Orphans, LEFT JOIN shape: a NULL or dangling parent_id has to be visible,
  -- which an inner join would silently drop.
  SELECT count(*) INTO orphans
    FROM public.locations c
    LEFT JOIN public.locations p ON p.id = c.parent_id
   WHERE c.country_code = 'FR' AND c.type = 'municipality'
     AND (p.id IS NULL OR p.country_code <> 'FR' OR p.type <> 'district');

  IF orphans > 0 THEN
    RAISE EXCEPTION 'France GeoNames seed: % municipality rows are not parented to a district row in FR', orphans;
  END IF;

  -- Every seeded row is a GeoNames row, bar the 2 config-declared synthetic one(s).
  SELECT count(*) INTO n_keyless
    FROM public.locations
   WHERE country_code = 'FR' AND type IN ('country', 'region', 'district', 'municipality')
     AND geonames_id IS NULL;

  IF n_keyless <> 2 THEN
    RAISE EXCEPTION
      'France GeoNames seed: % seeded FR rows carry no geonames_id, expected 2',
      n_keyless;
  END IF;

  -- Every row at a level the config maps a code for carries one. A code-less
  -- row cannot be re-pointed by a reconciliation or joined by postal data.
  SELECT count(*) INTO n_codeless
    FROM public.locations
   WHERE country_code = 'FR' AND type IN ('region', 'district', 'municipality')
     AND external_code IS NULL;

  IF n_codeless > 0 THEN
    RAISE EXCEPTION
      'France GeoNames seed: % FR rows carry no external_code at a level that must have one',
      n_codeless;
  END IF;

  -- Codes are unique within (country, type) — the key every reconciliation and
  -- official-data join runs on.
  SELECT count(*) INTO n_dupes
    FROM (
      SELECT type, external_code
        FROM public.locations
       WHERE country_code = 'FR' AND external_code IS NOT NULL
       GROUP BY type, external_code
      HAVING count(*) > 1
    ) d;

  IF n_dupes > 0 THEN
    RAISE EXCEPTION 'France GeoNames seed: % (type, external_code) pairs are duplicated for FR', n_dupes;
  END IF;
END;
$$;

-- ---------------------------------------------------------------------------
-- 4. RE-POINT — every captured reference, against the rows that replaced them
-- ---------------------------------------------------------------------------
--
-- One join throughout: (country_code, type, external_code), with
-- `IS NOT DISTINCT FROM` so a code-less captured row still reaches the warning
-- report instead of silently vanishing from the join.

-- Resolved first, into a table, because the same resolution answers three
-- questions: where each site goes, which sites had nowhere to go, and whether
-- the join was a function rather than a fan-out (asserted in section 5).
CREATE TEMP TABLE cutover_site_targets ON COMMIT DROP AS
  SELECT c.site_id, c.site_name, c.parent_type, c.parent_code, n.id AS new_parent_id
    FROM cutover_sites c
    LEFT JOIN public.locations n
      ON n.country_code = 'FR'
     AND n.type = c.parent_type
     AND n.external_code IS NOT DISTINCT FROM c.parent_code;

UPDATE public.locations s
   SET parent_id = t.new_parent_id
  FROM cutover_site_targets t
 WHERE s.id = t.site_id
   AND t.new_parent_id IS NOT NULL;

-- A site whose old parent has no counterpart is parked under the country row.
-- Never NULL: a NULL parent is the picker's root level, so the venue would
-- surface beside the countries. Never deleted: a product may RESTRICT on it.
UPDATE public.locations s
   SET parent_id = c.id
  FROM cutover_site_targets t,
       cutover_country c
 WHERE s.id = t.site_id
   AND t.new_parent_id IS NULL;

INSERT INTO public.gedu_locations (gedu_id, location_id)
SELECT c.gedu_id, n.id
  FROM cutover_gedu c
  JOIN public.locations n
    ON n.country_code = 'FR'
   AND n.type = c.type
   AND n.external_code IS NOT DISTINCT FROM c.external_code;

UPDATE public.profiles p
   SET home_location_id = n.id
  FROM cutover_home c
  JOIN public.locations n
    ON n.country_code = 'FR'
   AND n.type = c.type
   AND n.external_code IS NOT DISTINCT FROM c.external_code
 WHERE p.id = c.profile_id;

-- Products, off the country row and back onto their captured (type, code).
-- This UPDATE runs the products location trigger, so a relic product whose
-- captured type its own shape forbids fails here with the trigger's message —
-- the correct, named outcome for a row that needs a human. One that maps to
-- nothing stays parked on the country row: legal where it stands, named below.
UPDATE public.products p
   SET location_id = n.id
  FROM cutover_products c
  JOIN public.locations n
    ON n.country_code = 'FR'
   AND n.type = c.type
   AND n.external_code IS NOT DISTINCT FROM c.external_code
 WHERE p.id = c.product_id;

-- The warning report. Empty is the expected outcome in production; staging's
-- location data is fake and explicitly disposable, so losses there are named
-- and accepted rather than fixed.
DO $$
DECLARE
  v_count integer;
  v_names text;
BEGIN
  SELECT count(*), string_agg(format('%s (was under %s %s)', site_name, parent_type, coalesce(parent_code, '-')), ', ' ORDER BY site_name)
    INTO v_count, v_names
    FROM cutover_site_targets
   WHERE new_parent_id IS NULL;

  IF v_count > 0 THEN
    RAISE WARNING
      'France cutover: % site(s) had no counterpart for their old parent and are parked under the FR country row: %',
      v_count, v_names;
  END IF;

  SELECT count(*), string_agg(format('gedu %s -> %s %s', c.gedu_id, c.type, coalesce(c.external_code, '-')), ', ' ORDER BY c.gedu_id, c.type)
    INTO v_count, v_names
    FROM cutover_gedu c
   WHERE NOT EXISTS (
     SELECT 1 FROM public.locations n
      WHERE n.country_code = 'FR'
        AND n.type = c.type
        AND n.external_code IS NOT DISTINCT FROM c.external_code
   );

  IF v_count > 0 THEN
    RAISE WARNING
      'France cutover: % gedu coverage tick(s) had no counterpart and are gone: %',
      v_count, v_names;
  END IF;

  SELECT count(*), string_agg(format('profile %s -> %s %s', c.profile_id, c.type, coalesce(c.external_code, '-')), ', ' ORDER BY c.profile_id)
    INTO v_count, v_names
    FROM cutover_home c
   WHERE NOT EXISTS (
     SELECT 1 FROM public.locations n
      WHERE n.country_code = 'FR'
        AND n.type = c.type
        AND n.external_code IS NOT DISTINCT FROM c.external_code
   );

  IF v_count > 0 THEN
    RAISE WARNING
      'France cutover: % family location pick(s) had no counterpart and are now empty: %',
      v_count, v_names;
  END IF;

  SELECT count(*), string_agg(format('product %s -> %s %s', c.product_id, c.type, coalesce(c.external_code, '-')), ', ' ORDER BY c.product_id)
    INTO v_count, v_names
    FROM cutover_products c
   WHERE NOT EXISTS (
     SELECT 1 FROM public.locations n
      WHERE n.country_code = 'FR'
        AND n.type = c.type
        AND n.external_code IS NOT DISTINCT FROM c.external_code
   );

  IF v_count > 0 THEN
    RAISE WARNING
      'France cutover: % product(s) had no counterpart and are parked on the FR country row — re-point them by hand: %',
      v_count, v_names;
  END IF;
END;
$$;

-- ---------------------------------------------------------------------------
-- 5. ASSERT — nothing crossed silently
-- ---------------------------------------------------------------------------
--
-- The seed gates above already refused a tree that did not land whole. What is
-- left to prove is that every reference into the old tree either landed in the
-- new one or was named in a warning, and that no site or product was left
-- somewhere the warnings did not say.
DO $$
DECLARE
  v_sites          integer;
  v_targets        integer;
  v_captured       integer;
  v_lost           integer;
  v_restored       integer;
  v_expected       integer;
BEGIN
  -- The code join has to be a function, not a fan-out: one target row per
  -- captured site, or the UPDATE above picked an arbitrary parent.
  SELECT count(*) INTO v_sites   FROM cutover_sites;
  SELECT count(*) INTO v_targets FROM cutover_site_targets;

  IF v_targets <> v_sites THEN
    RAISE EXCEPTION
      'France cutover: % captured site(s) resolved to % target row(s) — the (type, external_code) join is not unique',
      v_sites, v_targets;
  END IF;

  -- Gedu coverage: restored = captured - warned, counted over the level rows
  -- only — claims on the country row survived adoption uncaptured, so they are
  -- outside both sides of this equation.
  SELECT count(*) INTO v_captured FROM cutover_gedu;
  SELECT count(*) INTO v_lost
    FROM cutover_gedu c
   WHERE NOT EXISTS (
     SELECT 1 FROM public.locations n
      WHERE n.country_code = 'FR' AND n.type = c.type
        AND n.external_code IS NOT DISTINCT FROM c.external_code
   );
  SELECT count(*) INTO v_restored
    FROM public.gedu_locations gl
    JOIN public.locations n ON n.id = gl.location_id
   WHERE n.country_code = 'FR' AND n.type IN ('region', 'district', 'municipality');

  IF v_restored <> v_captured - v_lost THEN
    RAISE EXCEPTION
      'France cutover: captured % gedu coverage tick(s), warned about %, but % came back',
      v_captured, v_lost, v_restored;
  END IF;

  -- Family location picks, the same way.
  SELECT count(*) INTO v_captured FROM cutover_home;
  SELECT count(*) INTO v_lost
    FROM cutover_home c
   WHERE NOT EXISTS (
     SELECT 1 FROM public.locations n
      WHERE n.country_code = 'FR' AND n.type = c.type
        AND n.external_code IS NOT DISTINCT FROM c.external_code
   );
  SELECT count(*) INTO v_restored
    FROM public.profiles p
    JOIN public.locations n ON n.id = p.home_location_id
   WHERE n.country_code = 'FR' AND n.type IN ('region', 'district', 'municipality');

  IF v_restored <> v_captured - v_lost THEN
    RAISE EXCEPTION
      'France cutover: captured % family location pick(s), warned about %, but % came back',
      v_captured, v_lost, v_restored;
  END IF;

  -- Products: restored = captured - warned, over the level rows; the warned
  -- remainder is still parked on the country row and is counted just below.
  SELECT count(*) INTO v_captured FROM cutover_products;
  SELECT count(*) INTO v_lost
    FROM cutover_products c
   WHERE NOT EXISTS (
     SELECT 1 FROM public.locations n
      WHERE n.country_code = 'FR' AND n.type = c.type
        AND n.external_code IS NOT DISTINCT FROM c.external_code
   );
  SELECT count(*) INTO v_restored
    FROM public.products p
    JOIN public.locations n ON n.id = p.location_id
   WHERE n.country_code = 'FR' AND n.type IN ('region', 'district', 'municipality');

  IF v_restored <> v_captured - v_lost THEN
    RAISE EXCEPTION
      'France cutover: captured % product(s), warned about %, but % came back',
      v_captured, v_lost, v_restored;
  END IF;

  -- The products on the country row are exactly the ones that were already
  -- there before this ran plus the warned set — nothing else drifted onto it.
  SELECT coalesce(sum(pre_products), 0) + v_lost INTO v_expected FROM cutover_country;
  SELECT count(*) INTO v_restored
    FROM public.products p
    JOIN cutover_country c ON c.id = p.location_id;

  IF v_restored <> v_expected THEN
    RAISE EXCEPTION
      'France cutover: % product(s) sit on the FR country row, expected % (pre-existing plus the warned set)',
      v_restored, v_expected;
  END IF;

  -- No site left at the picker's root.
  SELECT count(*) INTO v_restored
    FROM public.locations
   WHERE type = 'site' AND country_code = 'FR' AND parent_id IS NULL;

  IF v_restored > 0 THEN
    RAISE EXCEPTION
      'France cutover: % FR site(s) have no parent and would surface beside the countries',
      v_restored;
  END IF;

  -- The sites sitting directly under the country row are exactly the ones that
  -- were already parked there before this ran — their parent survived, so they
  -- were never captured — plus the ones the warnings named.
  SELECT count(*) INTO v_lost
    FROM cutover_site_targets
   WHERE new_parent_id IS NULL;
  SELECT coalesce(sum(pre_sites), 0) + v_lost INTO v_expected FROM cutover_country;
  SELECT count(*) INTO v_restored
    FROM public.locations s
    JOIN cutover_country c ON c.id = s.parent_id
   WHERE s.type = 'site';

  IF v_restored <> v_expected THEN
    RAISE EXCEPTION
      'France cutover: % FR site(s) sit directly under the country row, expected % (pre-existing plus the warned set)',
      v_restored, v_expected;
  END IF;
END;
$$;

COMMIT;
